INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 3, 'theory', 'Quiz: caching and CDN');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 3, 0, 'How does the cache-aside pattern work on a miss?', '["The application returns an error", "It reads from the database, puts the result in the cache, and responds", "It waits for the cache to load the data itself", "It reads from a neighboring server"]', 1, 'On a miss the application reads the database and fills the cache, so the following requests get a hit.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 3, 1, 'What helps against a cache stampede?', '["Make the cache smaller", "Single flight and a random addition to the TTL", "Turn the cache off", "Add more databases"]', 1, 'While one request recomputes the value, the others wait; spreading out the TTL keeps keys from expiring at the same time.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 3, 2, 'How do you solve the problem of stale files in a CDN without an expensive cache purge?', '["Set the TTL to one second", "Add a version or a hash to the file name", "Turn the CDN off", "Wait for the files to expire by themselves"]', 1, 'The new version gets a new name; the old one simply stops being requested.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 3, 3, 'What kind of data is a write-back cache suitable for?', '["Payments", "View counters, where losing a few seconds is acceptable", "Account balances", "Passwords"]', 1, 'Write-back is faster and takes load off the database, but if the cache fails the data can be lost.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 3, 4, 'What happens if a system relies on a cache with a 90% hit ratio and the cache suddenly disappears?', '["Nothing", "The load on the database grows tenfold", "The load on the database grows by 10%", "The application server stops working"]', 1, 'The database used to get only 10% of reads and now gets all 100%: a tenfold increase; that is why caches are made redundant and warmed up.');
